bad_example:
fn factorial(n: int) -> int {
    if n <= 1 {
        return 1
    }
    return n * factorial(n - 1)
}

good_example:
fn factorial(n: int) -> int {
    let result: int = 1
    let i: int = n
    while i > 1 {
        result = result * i
        i = i - 1
    }
    return result
}

